// Host checks for dist_graph_replay.exe (include/mipt/graph_replay.hpp). No
// CUDA-Q, no GPU, no MOSEK.
//
// The reference is a synthetic "production" record file written the way
// PairProtocol writes one: the graph of every realization regenerated by the
// documented recipe -- spelled out again here, independently of
// graph_replay.hpp, so a drift in either shows up -- and the records laid out
// through the same records:: helpers PairProtocol calls (pair_header_text,
// pair_record_flags, fill_pair_diagnostic_values, RecordSink), with
// placeholder physics where the state vector would go. The same run is
// written twice, with the turn diagnostics off and on, and the checks are:
//
//   (a) augmenting the "off" file reproduces the "on" file byte for byte --
//       header, identifiers, stored values, turn values, flag bits -- and the
//       pieces are also checked one by one against an independently built
//       index, for a readable failure; 1 and 4 threads give identical bytes;
//       augmenting an augmented file (or the "on" file) reproduces it; the
//       caller's environment is restored afterwards
//   (b) a corrupted flag, gate value, turn value or turn bit is refused with
//       nothing left at the output path; a 1-ulp gate difference is accepted
//       (the cross-compiler tolerance) and reported; a header edited by one
//       byte is refused; a short trajectory before the end is refused
//   (c) record_stride > 1, the fswap_network boundary, and qRPPU all work
//   (d) an unfinished final trajectory is dropped and reported; the
//       MIPT_GRAPH_REPLAY_MAX_REALIZATIONS prefix is a prefix of the "on" file
//   (e) `paths` writes the documented header, realization order, file
//       orientation, and per-pair values matching pair_turns; it agrees on
//       the "off" and "on" inputs; bad selections are refused
//   (f) the CLI's exit statuses and default output names

#include "mipt/graph_replay.hpp"

#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <random>
#include <sstream>
#include <string>
#include <vector>

namespace
{
namespace gr = mipt::dist::graph_replay;
namespace records = mipt::dist::records;
using mipt::CircuitType;
using mipt::LogicalHistory;
using mipt::RppuLayer;
using mipt::dist::ConnectivityIndex;
using mipt::dist::GatePathMetrics;
using mipt::dist::PairConnectivity;
using mipt::dist::PairTurns;
using mipt::dist::RunConfig;

int failures = 0;

void expect(bool condition, const std::string &what)
{
    if (!condition)
    {
        ++failures;
        std::cerr << "FAIL: " << what << '\n';
    }
}

std::string scratch_directory()
{
    const auto path = std::filesystem::temp_directory_path() / "mipt_graph_replay_tests";
    std::filesystem::remove_all(path);
    std::filesystem::create_directories(path);
    return path.string();
}

std::string read_bytes(const std::string &path)
{
    std::ifstream in(path, std::ios::binary);
    std::ostringstream out;
    out << in.rdbuf();
    return out.str();
}

void write_bytes(const std::string &path, const std::string &bytes)
{
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
}

bool exists(const std::string &path)
{
    return std::filesystem::exists(path);
}

std::uint64_t bits(double value)
{
    std::uint64_t out = 0;
    std::memcpy(&out, &value, sizeof(out));
    return out;
}

// --------------------------------------------------------------- production

// The engine knobs the "production" run records. Deliberately not the
// defaults, so a replay that rendered them from its own environment or from the
// defaults instead of from the header would fail the reconstruction proof.
constexpr const char *CUSV_PARITY = "0";
constexpr const char *CUSV_MEASURE_BITS = "12";
constexpr const char *CUSV_BLOCK_TARGETS = "6";

RunConfig base_config(CircuitType type)
{
    RunConfig config;
    config.k = 2;
    config.n = 8;
    config.periods = 4;
    config.p = 0.3;
    config.realizations = 6;
    config.type = type;
    config.record_detail = mipt::dist::RecordDetail::Channel;
    config.record_stride = 1;
    config.pair_zero_tol = 1.0e-12;
    config.occupation_mi_tol = 1.0e-12;
    config.statevector_precision = 64;
    config.channel_floor = mipt::dist::default_channel_floor(64);
    config.seed = 20261015u;
    config.connectivity = true;
    config.gate_path_diagnostics = true;
    config.turn_diagnostics = false;
    return config;
}

// The recipe, verbatim from the contract and Circuit1D::seed: an independent
// copy of what graph_replay::regenerate_graph does.
ConnectivityIndex regenerate_independently(const RunConfig &config, bool jw, std::uint32_t realization,
                                           bool turns)
{
    const std::uint64_t value = mipt::seeding::trajectory_seed(config.seed, realization);
    std::seed_seq sequence{static_cast<std::uint32_t>(value & 0xffffffffu),
                           static_cast<std::uint32_t>(value >> 32)};
    std::mt19937 rng;
    rng.seed(sequence);
    std::vector<RppuLayer> layers;
    if (config.type == CircuitType::FermionRPPU)
    {
        mipt::build_rppu_layers(layers, config.n, config.periods, config.p, true, rng, jw);
    }
    else
    {
        mipt::build_qrppu_layers(layers, config.n, config.periods, config.p, true, rng);
    }
    const LogicalHistory history = mipt::logical_history_from_rppu(layers, config.n);
    ConnectivityIndex index;
    index.build(history, true, true, turns);
    return index;
}

// PairProtocol's enumeration: all_unordered_pairs order, per-separation counters.
std::vector<std::array<int, 4>> embedding_rows(int n)
{
    std::vector<std::array<int, 4>> rows;
    std::vector<int> seen(static_cast<std::size_t>(n / 2), 0);
    for (int i = 0; i < n; ++i)
    {
        for (int j = i + 1; j < n; ++j)
        {
            const int bin = mipt::util::periodic_distance(i, j, n) - 1;
            rows.push_back({bin, seen[static_cast<std::size_t>(bin)]++, i, j});
        }
    }
    return rows;
}

double placeholder(std::uint32_t realization, std::size_t pair, std::size_t slot)
{
    const std::uint64_t x = mipt::seeding::splitmix64((static_cast<std::uint64_t>(realization) << 32) ^
                                                      (static_cast<std::uint64_t>(pair) << 8) ^ slot);
    return static_cast<double>(x >> 11) * 0x1.0p-53;
}

// Pins the environment the header renderer reads for the duration of one write.
struct ProductionEnvironment
{
    gr::detail::ScopedEnvironment environment;
    ProductionEnvironment(const RunConfig &config, bool jw)
    {
        if (config.type == CircuitType::FermionRPPU)
        {
            environment.set("MIPT_DIRECT_FERMION_BOUNDARY", jw ? "1" : "0");
        }
        environment.set("MIPT_CUSV_PARITY", CUSV_PARITY);
        environment.set("MIPT_CUSV_MEASURE_BITS", CUSV_MEASURE_BITS);
        environment.set("MIPT_CUSV_BLOCK_TARGETS", CUSV_BLOCK_TARGETS);
    }
};

std::string production_header(const RunConfig &config, bool jw)
{
    ProductionEnvironment environment(config, jw);
    return records::pair_header_text(config, mipt::dist::make_pair_bins(config.n),
                                     embedding_rows(config.n));
}

// What PairProtocol::measure writes for every kept realization below
// config.realizations, with placeholder physics.
void write_production(const std::string &path, const RunConfig &config, bool jw)
{
    std::filesystem::remove(path);
    const std::string header = production_header(config, jw);
    const std::vector<std::string> names = records::pair_observable_names(config);
    const std::size_t detail = records::pair_detail_observable_names(config).size();
    const std::size_t expected = detail +
                                 (config.gate_path_diagnostics ? records::GATE_RECORD_VALUES : 0u) +
                                 (config.turn_diagnostics ? records::TURN_RECORD_VALUES : 0u);
    expect(names.size() == expected, "pair_observable_names is detail + gate + turn values");
    auto slot = [&](const char *name) {
        return static_cast<std::size_t>(std::find(names.begin(), names.end(), name) - names.begin());
    };
    const std::size_t mn = slot("mn");
    const std::size_t fmn = slot("fmn");
    const std::size_t g2 = slot("g2");
    const std::size_t f2 = slot("f2");
    const auto rows = embedding_rows(config.n);

    records::RecordSink sink;
    sink.open(path, header, names.size(), 0);
    std::vector<double> values(names.size());
    for (int realization = 0; realization < config.realizations; ++realization)
    {
        if (!records::stride_selects(config.record_stride, static_cast<std::uint64_t>(realization)))
        {
            continue;
        }
        const std::uint32_t r = static_cast<std::uint32_t>(realization);
        const ConnectivityIndex index = regenerate_independently(config, jw, r, config.turn_diagnostics);
        for (std::size_t pair = 0; pair < rows.size(); ++pair)
        {
            const int i = rows[pair][2];
            const int j = rows[pair][3];
            const PairConnectivity conn = index.query(i, j);
            const GatePathMetrics gate = index.gate_path_metrics(i, j);
            const PairTurns turns = config.turn_diagnostics ? index.pair_turns(i, j) : PairTurns{};
            for (std::size_t s = 0; s < detail; ++s)
            {
                values[s] = placeholder(r, pair, s);
            }
            // Exact zeros where the physics has them, and two values whose bits
            // a careless copy would not preserve.
            values[mn] = conn.connected ? 0.01 + values[mn] : 0.0;
            values[fmn] = (conn.connected && pair % 4 != 0) ? values[fmn] : 0.0;
            if (pair % 5 == 2)
            {
                const std::uint64_t payload = 0x7ff8dead00000001ull;
                std::memcpy(&values[g2], &payload, sizeof(double));
            }
            if (pair % 7 == 1)
            {
                values[f2] = -0.0;
            }
            const std::uint32_t flags = records::pair_record_flags(
                conn, values[fmn] > config.pair_zero_tol, values[mn] > config.pair_zero_tol, turns);
            records::fill_pair_diagnostic_values(config, conn, gate, turns, values.data() + detail);
            sink.add(r, static_cast<std::uint32_t>(rows[pair][0]),
                     static_cast<std::uint32_t>(rows[pair][1]), flags, values.data());
        }
    }
    sink.close();
}

struct RunFiles
{
    RunConfig config;
    bool jw = true;
    std::string off;
    std::string on;
};

RunFiles make_run(const std::string &directory, const std::string &stem, RunConfig config, bool jw)
{
    RunFiles files;
    files.config = config;
    files.jw = jw;
    files.off = directory + "/" + stem + "_records.bin";
    files.on = directory + "/" + stem + "_on_records.bin";
    config.turn_diagnostics = false;
    write_production(files.off, config, jw);
    config.turn_diagnostics = true;
    write_production(files.on, config, jw);
    return files;
}

gr::AugmentSummary run_augment(const std::string &in, const std::string &out, int threads,
                               std::uint64_t max_realizations = 0)
{
    gr::AugmentOptions options;
    options.input_path = in;
    options.output_path = out;
    options.threads = threads;
    options.max_realizations = max_realizations;
    options.log = nullptr;
    return gr::augment(options);
}

// Expects augment to refuse with a ValidationError whose message contains
// `needle`, leaving neither the output nor its partial file.
void expect_refused(const std::string &in, const std::string &out, const std::string &needle,
                    const std::string &what)
{
    bool refused = false;
    try
    {
        run_augment(in, out, 2);
    }
    catch (const gr::ValidationError &error)
    {
        refused = true;
        expect(std::string(error.what()).find(needle) != std::string::npos,
               what + ": message names `" + needle + "` (got: " + error.what() + ")");
    }
    catch (const std::exception &error)
    {
        expect(false, what + ": wrong exception type: " + error.what());
    }
    expect(refused, what + ": refused");
    expect(!exists(out) && !exists(out + ".partial"), what + ": nothing left at the output path");
}

std::size_t payload_offset(const std::string &bytes)
{
    std::uint32_t header = 0;
    std::memcpy(&header, bytes.data() + 16, 4);
    return records::PREAMBLE_BYTES + header;
}

// Overwrite one stored double (observable `name`) of record `index`.
std::string with_value(std::string bytes, const records::RecordReader &reader, std::uint64_t index,
                       const std::string &name, double value)
{
    const std::size_t offset = payload_offset(bytes) + index * reader.record_bytes() +
                               records::ID_BYTES +
                               static_cast<std::size_t>(reader.observable_index(name)) * sizeof(double);
    std::memcpy(bytes.data() + offset, &value, sizeof(double));
    return bytes;
}

std::string with_flags(std::string bytes, const records::RecordReader &reader, std::uint64_t index,
                       std::uint32_t flags)
{
    std::memcpy(bytes.data() + payload_offset(bytes) + index * reader.record_bytes() + 8, &flags, 4);
    return bytes;
}

// The first record of `reader` that is connected (and so has finite gate values).
std::uint64_t first_connected(records::RecordReader &reader)
{
    for (std::uint64_t k = 0; k < reader.record_count(); ++k)
    {
        if ((reader.read_at(k).flags & mipt::dist::FLAG_CONNECTED) != 0u)
        {
            return k;
        }
    }
    return 0;
}

// --------------------------------------------------------------- (a) augment

void test_augment_reproduces_live_run(const std::string &directory)
{
    const RunFiles run = make_run(directory, "rppu", base_config(CircuitType::FermionRPPU), true);
    const std::string augmented = directory + "/rppu_turns_records.bin";

    // The caller's environment, which the replay must override for the
    // rendering and then hand back.
    ::setenv("MIPT_CUSV_BLOCK_TARGETS", "4", 1);
    ::unsetenv("MIPT_DIRECT_FERMION_BOUNDARY");
    const gr::AugmentSummary summary = run_augment(run.off, augmented, 1);
    expect(std::getenv("MIPT_CUSV_BLOCK_TARGETS") != nullptr &&
               std::string(std::getenv("MIPT_CUSV_BLOCK_TARGETS")) == "4",
           "augment restores the caller's MIPT_CUSV_BLOCK_TARGETS");
    expect(std::getenv("MIPT_DIRECT_FERMION_BOUNDARY") == nullptr,
           "augment leaves MIPT_DIRECT_FERMION_BOUNDARY unset again");
    ::unsetenv("MIPT_CUSV_BLOCK_TARGETS");

    const std::size_t per_trajectory = 28;
    expect(summary.realizations == 6 && summary.records == 6 * per_trajectory,
           "augment replays every trajectory");
    expect(summary.mismatches == 0 && summary.dropped_records == 0 && summary.dropped_bytes == 0,
           "a clean file has no mismatch and no tail");
    expect(summary.agreement.compared > 0 && summary.agreement.inexact == 0,
           "same-compiler gate values agree bit for bit");
    expect(!summary.input_had_turns, "the off file has no turn values");
    expect(read_bytes(augmented) == read_bytes(run.on),
           "augmenting the turns-off file reproduces the turns-on live file byte for byte");

    // The same, piece by piece, for a readable failure.
    RunConfig on = run.config;
    on.turn_diagnostics = true;
    records::RecordReader out(augmented);
    records::RecordReader in(run.off);
    expect(out.header_text() == production_header(on, true),
           "the output header is pair_header_text with the turn diagnostics on");
    expect(out.field("flag_bits").find("9:connected_doubled") != std::string::npos,
           "the output's flag_bits line names the turn bits");
    expect(out.record_count() == in.record_count(), "one output record per input record");
    const auto &turn_names = records::turn_observable_names();
    bool identifiers = true;
    bool stored = true;
    bool turn_values = true;
    bool turn_bits = true;
    std::size_t with_turn_bits = 0;
    const auto sites_of = in.embedding_sites();
    ConnectivityIndex index;
    std::int64_t indexed = -1;
    for (std::uint64_t k = 0; k < in.record_count(); ++k)
    {
        const records::StoredRecord a = in.read_at(k);
        const records::StoredRecord b = out.read_at(k);
        if (static_cast<std::int64_t>(a.realization) != indexed)
        {
            index = regenerate_independently(run.config, true, a.realization, true);
            indexed = static_cast<std::int64_t>(a.realization);
        }
        identifiers = identifiers && a.realization == b.realization && a.geometry == b.geometry &&
                      a.embedding == b.embedding &&
                      (a.flags & ~gr::TURN_FLAG_BITS) == (b.flags & ~gr::TURN_FLAG_BITS);
        for (std::size_t s = 0; s < a.values.size(); ++s)
        {
            stored = stored && bits(a.values[s]) == bits(b.values[s]);
        }
        const auto &sites = sites_of.at({a.geometry, a.embedding});
        const PairConnectivity conn = index.query(sites[0], sites[1]);
        const PairTurns turns = index.pair_turns(sites[0], sites[1]);
        std::array<double, records::TURN_RECORD_VALUES> expected{};
        records::fill_turn_record_values(conn, turns, expected.data());
        for (std::size_t t = 0; t < expected.size(); ++t)
        {
            turn_values = turn_values &&
                          bits(b.values[static_cast<std::size_t>(out.observable_index(turn_names[t]))]) ==
                              bits(expected[t]);
        }
        turn_bits = turn_bits && (b.flags & gr::TURN_FLAG_BITS) == turns.flags() &&
                    (conn.connected || (b.flags & gr::TURN_FLAG_BITS) == 0u);
        with_turn_bits += (b.flags & gr::TURN_FLAG_BITS) != 0u ? 1u : 0u;
    }
    expect(identifiers, "identifiers and flag bits 0-6 are carried through unchanged");
    expect(stored, "every stored value is carried through bit for bit (NaN payload, -0.0)");
    expect(turn_values, "turn values equal fill_turn_record_values of an independent index");
    expect(turn_bits, "turn flag bits equal PairTurns::flags() and vanish off C");
    expect(with_turn_bits > 0, "the fixture exercises the turn flag bits");

    const std::string four = directory + "/rppu_turns4_records.bin";
    run_augment(run.off, four, 4);
    expect(read_bytes(four) == read_bytes(augmented), "1 and 4 threads give identical bytes");

    const std::string again = directory + "/rppu_turns_turns_records.bin";
    const gr::AugmentSummary second = run_augment(augmented, again, 3);
    expect(second.input_had_turns, "an augmented file is recognised as carrying turn values");
    expect(read_bytes(again) == read_bytes(augmented), "augmenting an augmented file reproduces it");

    const std::string live = directory + "/rppu_on_again_records.bin";
    run_augment(run.on, live, 2);
    expect(read_bytes(live) == read_bytes(run.on), "augmenting the live turns-on file reproduces it");
}

// ------------------------------------------------------------ (b) refusals

void test_refusals(const std::string &directory)
{
    const RunFiles run = make_run(directory, "bad", base_config(CircuitType::FermionRPPU), true);
    const std::string original = read_bytes(run.off);
    const std::string corrupt = directory + "/bad_corrupt_records.bin";
    const std::string out = directory + "/bad_out_records.bin";
    records::RecordReader reader(run.off);
    const std::uint64_t connected = first_connected(reader);
    const records::StoredRecord record = reader.read_at(connected);

    write_bytes(corrupt, with_flags(original, reader, connected, record.flags ^ mipt::dist::FLAG_CONNECTED));
    expect_refused(corrupt, out, "connectivity flags", "a flipped connected bit");

    write_bytes(corrupt, with_flags(original, reader, connected, record.flags | (1u << 12)));
    expect_refused(corrupt, out, "bit12", "an unknown flag bit");

    const double widest = record.values[static_cast<std::size_t>(reader.observable_index("widest_gate_ep"))];
    write_bytes(corrupt, with_value(original, reader, connected, "widest_gate_ep", widest + 1.0e-9));
    expect_refused(corrupt, out, "widest_gate_ep", "a gate value off by 1e-9");

    const double count =
        record.values[static_cast<std::size_t>(reader.observable_index("shortest_path_unitary_count"))];
    write_bytes(corrupt, with_value(original, reader, connected, "shortest_path_unitary_count",
                                    std::nextafter(count, 1.0e9)));
    expect_refused(corrupt, out, "shortest_path_unitary_count", "an integer gate field off by one ulp");

    write_bytes(corrupt, with_value(original, reader, connected, "widest_gate_ep",
                                    std::numeric_limits<double>::quiet_NaN()));
    expect_refused(corrupt, out, "widest_gate_ep", "a finite gate value stored as NaN");

    // One ulp on a continuous capacity is what a different compiler gives,
    // and is accepted -- and reported.
    write_bytes(corrupt, with_value(original, reader, connected, "widest_gate_ep",
                                    std::nextafter(widest, 2.0)));
    const gr::AugmentSummary ulp = run_augment(corrupt, out, 2);
    expect(ulp.agreement.inexact == 1 && ulp.agreement.max_difference > 0.0 &&
               ulp.agreement.max_difference < 1.0e-15,
           "a 1-ulp capacity difference is accepted and reported");
    std::filesystem::remove(out);

    // A record file that already carries turn values is held to them.
    const std::string on_original = read_bytes(run.on);
    records::RecordReader on_reader(run.on);
    const records::StoredRecord on_record = on_reader.read_at(connected);
    const double turns = on_record.values[static_cast<std::size_t>(on_reader.observable_index("min_turns"))];
    write_bytes(corrupt, with_value(on_original, on_reader, connected, "min_turns", turns + 2.0));
    expect_refused(corrupt, out, "min_turns", "a corrupted stored turn value");
    write_bytes(corrupt, with_flags(on_original, on_reader, connected,
                                    on_record.flags ^ mipt::dist::FLAG_CONNECTED_DOUBLED));
    expect_refused(corrupt, out, "turn flags", "a flipped turn flag bit");

    // The reconstruction proof: one byte of the header changed.
    std::string edited = original;
    const std::size_t at = edited.find("entropy_units=bits");
    expect(at != std::string::npos, "the fixture header carries entropy_units");
    edited[at + std::strlen("entropy_units=bit")] = 'z';
    write_bytes(corrupt, edited);
    expect_refused(corrupt, out, "entropy_units=bitz", "a header edited by one byte");

    edited = original;
    const std::size_t seed = edited.find("master_seed=20261015");
    edited[seed + std::strlen("master_seed=2026101")] = '6';
    write_bytes(corrupt, edited);
    expect_refused(corrupt, out, "", "a header whose master seed was edited");

    // A short trajectory that is not the last one: drop one record of the
    // second trajectory.
    std::string short_one = original;
    const std::size_t record_bytes = reader.record_bytes();
    short_one.erase(payload_offset(original) + (28 + 3) * record_bytes, record_bytes);
    write_bytes(corrupt, short_one);
    expect_refused(corrupt, out, "a whole trajectory holds 28", "a short trajectory before the end");

    // The CLI on a corrupted file: status 3 and nothing written.
    write_bytes(corrupt, with_flags(original, reader, connected, record.flags ^ mipt::dist::FLAG_SURVIVES_I));
    std::ostringstream sink_out;
    std::ostringstream sink_err;
    const int status = gr::cli_main({"dist_graph_replay.exe", "augment", corrupt, out}, sink_out, sink_err);
    expect(status == gr::STATUS_VALIDATION, "the CLI exits 3 on a validation failure");
    expect(!exists(out) && !exists(out + ".partial"), "the CLI leaves no output after a failure");
    expect(sink_err.str().find("VALIDATION FAILED") != std::string::npos, "the CLI says so");
}

// ---------------------------------------------- (c) stride, boundary, qRPPU

void test_variants(const std::string &directory)
{
    RunConfig strided = base_config(CircuitType::FermionRPPU);
    strided.realizations = 7;
    strided.record_stride = 3;
    const RunFiles stride = make_run(directory, "stride", strided, true);
    const std::string out = directory + "/stride_turns_records.bin";
    const gr::AugmentSummary summary = run_augment(stride.off, out, 3);
    expect(summary.realizations == 3, "record_stride=3 over 7 keeps realizations 0, 3, 6");
    expect(read_bytes(out) == read_bytes(stride.on), "a strided file augments to the live strided file");

    const RunFiles fswap = make_run(directory, "fswap", base_config(CircuitType::FermionRPPU), false);
    const std::string fswap_out = directory + "/fswap_turns_records.bin";
    run_augment(fswap.off, fswap_out, 2);
    expect(read_bytes(fswap_out) == read_bytes(fswap.on), "the fswap_network boundary augments exactly");
    expect(records::RecordReader(fswap_out).field("boundary_implementation") == "fswap_network",
           "and is recorded as fswap_network");

    const RunFiles qubit = make_run(directory, "qrppu", base_config(CircuitType::QubitRPPU), true);
    const std::string qubit_out = directory + "/qrppu_turns_records.bin";
    run_augment(qubit.off, qubit_out, 2);
    expect(read_bytes(qubit_out) == read_bytes(qubit.on), "qRPPU augments exactly");

    // A file without the gate diagnostics is not something the tool reads.
    RunConfig plain = base_config(CircuitType::FermionRPPU);
    plain.gate_path_diagnostics = false;
    const std::string plain_path = directory + "/plain_records.bin";
    write_production(plain_path, plain, true);
    bool refused = false;
    try
    {
        run_augment(plain_path, directory + "/plain_out_records.bin", 1);
    }
    catch (const gr::UsageError &)
    {
        refused = true;
    }
    expect(refused, "a file without MIPT_DIST_GATE_DIAGNOSTICS is refused as a usage error");
}

// ------------------------------------------------------- (d) tail and prefix

void test_tail_and_prefix(const std::string &directory)
{
    const RunFiles run = make_run(directory, "tail", base_config(CircuitType::FermionRPPU), true);
    const std::string off = read_bytes(run.off);
    const std::string on = read_bytes(run.on);
    records::RecordReader reader(run.off);
    records::RecordReader on_reader(run.on);
    const std::size_t in_bytes = reader.record_bytes();
    const std::size_t out_bytes = on_reader.record_bytes();
    const std::size_t per_trajectory = 28;

    // Five whole records and seven bytes short of the end: the last
    // trajectory keeps 22 whole records and a partial one.
    const std::string truncated = directory + "/tail_cut_records.bin";
    write_bytes(truncated, off.substr(0, off.size() - 5 * in_bytes - 7));
    const std::string out = directory + "/tail_cut_turns_records.bin";
    const gr::AugmentSummary summary = run_augment(truncated, out, 2);
    expect(summary.realizations == 5, "an unfinished last trajectory is dropped");
    expect(summary.dropped_records == per_trajectory - 6 && summary.dropped_bytes == in_bytes - 7,
           "and the dropped records and bytes are reported");
    expect(read_bytes(out) == on.substr(0, payload_offset(on) + 5 * per_trajectory * out_bytes),
           "the output is the live file's first five trajectories");

    const std::string prefix = directory + "/tail_prefix_turns_records.bin";
    const gr::AugmentSummary limited = run_augment(run.off, prefix, 2, 2);
    expect(limited.limited && limited.realizations == 2, "max_realizations stops after two");
    expect(read_bytes(prefix) == on.substr(0, payload_offset(on) + 2 * per_trajectory * out_bytes),
           "the limited output is a prefix of the live file");
}

// ------------------------------------------------------------------ (e) paths

std::vector<std::string> split(const std::string &line)
{
    return gr::detail::split_csv_line(line);
}

void test_paths(const std::string &directory)
{
    const RunFiles run = make_run(directory, "paths", base_config(CircuitType::FermionRPPU), true);
    const std::string selection = directory + "/paths_turn_selection.csv";
    {
        // Columns out of order, an extra one, a reversed pair, a realization
        // listed twice and out of order.
        std::ofstream csv(selection);
        csv << "group,extra,pair_j,realization_id,pair_i\n"
            << "gap,x,5,3,1\n"
            << "control,y,0,1,7\n"
            << "gap,z,2,1,6\n"
            << "control,w,4,3,3\n"
            << "gap,v,1,0,0\n";
    }
    gr::PathsOptions options;
    options.records_path = run.off;
    options.selection_path = selection;
    options.threads = 2;
    options.log = nullptr;
    const gr::PathsSummary summary = gr::paths(options);
    expect(summary.output_path == directory + "/paths_turn_selection_paths.csv",
           "the default paths output is <selection stem>_paths.csv");
    expect(summary.rows == 5 && summary.realizations == 3, "one row per selected pair");
    expect(summary.validated_records == 3 * 28, "every record of each touched realization is validated");

    options.records_path = run.on;
    options.output_path = directory + "/paths_from_on.csv";
    gr::paths(options);
    expect(read_bytes(options.output_path) == read_bytes(summary.output_path),
           "paths agrees on the turns-off and turns-on inputs");

    std::ifstream in(summary.output_path);
    std::string line;
    std::getline(in, line);
    expect(line == gr::paths_csv_header(), "paths writes the documented header");
    const std::vector<std::string> header = split(line);
    expect(header.size() == 16 + 2 * gr::path_column_names().size(), "16 pair columns and two path blocks");
    std::map<std::string, std::size_t> column;
    for (std::size_t k = 0; k < header.size(); ++k)
    {
        column[header[k]] = k;
    }
    // Realization order, selection order within one, file orientation.
    const std::vector<std::array<int, 3>> expected_rows{{0, 0, 1}, {1, 0, 7}, {1, 2, 6}, {3, 1, 5}, {3, 3, 4}};
    const std::vector<std::string> expected_groups{"gap", "control", "gap", "gap", "control"};
    std::size_t row = 0;
    bool any_connected = false;
    bool any_disconnected = false;
    while (std::getline(in, line))
    {
        const std::vector<std::string> cells = split(line);
        expect(cells.size() == header.size(), "every paths row is complete");
        if (row >= expected_rows.size() || cells.size() != header.size())
        {
            ++row;
            continue;
        }
        const auto [r, i, j] = expected_rows[row];
        expect(cells[column["realization_id"]] == std::to_string(r) &&
                   cells[column["pair_i"]] == std::to_string(i) &&
                   cells[column["pair_j"]] == std::to_string(j),
               "paths row " + std::to_string(row) + " is (" + std::to_string(r) + ", " +
                   std::to_string(i) + ", " + std::to_string(j) + ")");
        expect(cells[column["group"]] == expected_groups[row], "the group is carried through");

        const ConnectivityIndex index =
            regenerate_independently(run.config, true, static_cast<std::uint32_t>(r), true);
        const PairConnectivity conn = index.query(i, j);
        const PairTurns turns = index.pair_turns(i, j);
        const std::string where = "paths row " + std::to_string(row) + ": ";
        expect(cells[column["connected"]] == (conn.connected ? "1" : "0"), where + "connected");
        expect(cells[column["component_size"]] == std::to_string(conn.component_size), where + "component_size");
        expect(cells[column["separation"]] == std::to_string(mipt::util::periodic_distance(i, j, 8)),
               where + "separation");
        expect(cells[column["doubled_network"]] == (turns.doubled_network ? "1" : "0") &&
                   cells[column["connected_doubled"]] == (turns.connected_doubled ? "1" : "0") &&
                   cells[column["certified"]] == (turns.certified ? "1" : "0"),
               where + "pair-level verdicts");
        if (conn.connected && turns.shortest_maximin.available)
        {
            any_connected = true;
            expect(cells[column["min_turns"]] == std::to_string(turns.min_turns), where + "min_turns");
            expect(cells[column["sm_class"]] == mipt::dist::path_class_name(turns.shortest_maximin.path_class),
                   where + "sm_class");
            expect(cells[column["wd_turns"]] == std::to_string(turns.widest.turns), where + "wd_turns");
            expect(cells[column["sm_cancelled_gates"]] == std::to_string(turns.shortest_maximin.cancelled_gates),
                   where + "sm_cancelled_gates");
            std::string gate_layers;
            for (std::size_t k = 0; k < turns.shortest_maximin.gate_layers.size(); ++k)
            {
                gate_layers += (k == 0 ? "" : ";") + std::to_string(turns.shortest_maximin.gate_layers[k]);
            }
            expect(cells[column["sm_gate_layers"]] == gate_layers, where + "sm_gate_layers");
            const mipt::dist::GraphPath trace = index.widest_gate_trace(i, j);
            std::string nodes;
            for (std::size_t k = 0; k < trace.nodes.size(); ++k)
            {
                nodes += (k == 0 ? "" : ";") + std::to_string(index.node_layer(trace.nodes[k])) + "." +
                         std::to_string(index.node_mode(trace.nodes[k]));
            }
            expect(cells[column["wd_nodes"]] == nodes, where + "wd_nodes in path order");
            expect(cells[column["wd_length"]] == std::to_string(trace.edges.size()), where + "wd_length");
        }
        else
        {
            any_disconnected = true;
            expect(cells[column["sm_class"]] == "nan" && cells[column["wd_nodes"]] == "nan" &&
                       cells[column["min_turns"]] == "nan" && cells[column["shortest_path"]] == "nan",
                   where + "an unconnected pair's path fields are nan");
        }
        ++row;
    }
    expect(row == expected_rows.size(), "paths writes exactly the selected rows");
    expect(any_connected, "the paths fixture has a connected pair");
    if (!any_disconnected)
    {
        std::cout << "note: the paths fixture happened to select no unconnected pair.\n";
    }

    // Selections that do not belong to the file.
    auto refused = [&](const std::string &body, const std::string &what) {
        std::ofstream(selection, std::ios::trunc) << body;
        options.records_path = run.off;
        options.output_path = directory + "/paths_refused.csv";
        bool usage = false;
        try
        {
            gr::paths(options);
        }
        catch (const gr::UsageError &)
        {
            usage = true;
        }
        expect(usage, what + " is refused");
        expect(!exists(options.output_path), what + ": nothing written");
    };
    refused("realization_id,pair_i,pair_j\n0,0,1\n", "a selection without a group column");
    refused("realization_id,pair_i,pair_j,group\n0,2,2,gap\n", "a pair of one site");
    refused("realization_id,pair_i,pair_j,group\n9,0,1,gap\n", "a realization past the run");

    // A corrupted record anywhere in a selected realization fails the row.
    const std::string original = read_bytes(run.off);
    records::RecordReader reader(run.off);
    const std::string corrupt = directory + "/paths_corrupt_records.bin";
    const std::uint64_t index = 28 + first_connected(reader) % 28; // realization 1
    const records::StoredRecord stored = reader.read_at(index);
    write_bytes(corrupt, with_flags(original, reader, index, stored.flags ^ mipt::dist::FLAG_INTERIOR_PATH));
    std::ofstream(selection, std::ios::trunc) << "realization_id,pair_i,pair_j,group\n1,0,7,gap\n";
    options.records_path = corrupt;
    options.output_path = directory + "/paths_corrupt.csv";
    bool validation = false;
    try
    {
        gr::paths(options);
    }
    catch (const gr::ValidationError &)
    {
        validation = true;
    }
    expect(validation, "paths validates every record of a selected realization");
    expect(!exists(options.output_path), "and writes nothing when one disagrees");
}

// -------------------------------------------------------------------- (f) CLI

void test_cli(const std::string &directory)
{
    std::ostringstream out;
    std::ostringstream err;
    expect(gr::cli_main({"dist_graph_replay.exe"}, out, err) == gr::STATUS_USAGE, "no command exits 2");
    expect(gr::cli_main({"dist_graph_replay.exe", "--help"}, out, err) == gr::STATUS_OK, "--help exits 0");
    expect(out.str().find("augment <in_records.bin>") != std::string::npos, "--help prints the usage");
    expect(gr::cli_main({"dist_graph_replay.exe", "augment"}, out, err) == gr::STATUS_USAGE,
           "augment without a file exits 2");
    expect(gr::cli_main({"dist_graph_replay.exe", "augment", directory + "/missing_records.bin"}, out, err) ==
               gr::STATUS_USAGE,
           "a missing input exits 2");
    expect(gr::cli_main({"dist_graph_replay.exe", "frobnicate", "x"}, out, err) == gr::STATUS_USAGE,
           "an unknown command exits 2");
    expect(gr::cli_main({"dist_graph_replay.exe", "paths", "a"}, out, err) == gr::STATUS_USAGE,
           "paths without a selection exits 2");
    expect(gr::default_augment_output("csv/run_records.bin") == "csv/run_turns_records.bin",
           "the default augment output replaces _records.bin");
    expect(gr::default_augment_output("csv/run.bin") == "csv/run_turns_records.bin",
           "and otherwise replaces .bin");
    expect(gr::default_paths_output("csv/run_turn_selection.csv") == "csv/run_turn_selection_paths.csv",
           "the default paths output is <selection stem>_paths.csv");

    // An input written as its own output would be destroyed; refused.
    const RunFiles run = make_run(directory, "self", base_config(CircuitType::FermionRPPU), true);
    expect(gr::cli_main({"dist_graph_replay.exe", "augment", run.off, run.off}, out, err) == gr::STATUS_USAGE,
           "augmenting a file onto itself exits 2");
    const std::string ok = directory + "/self_turns_records.bin";
    expect(gr::cli_main({"dist_graph_replay.exe", "augment", run.off}, out, err) == gr::STATUS_OK &&
               exists(ok),
           "augment with the default output exits 0 and writes it");
}

} // namespace

int main()
{
    const std::string directory = scratch_directory();
    test_augment_reproduces_live_run(directory);
    test_refusals(directory);
    test_variants(directory);
    test_tail_and_prefix(directory);
    test_paths(directory);
    test_cli(directory);
    std::filesystem::remove_all(directory);
    if (failures != 0)
    {
        std::cerr << failures << " graph-replay check(s) failed.\n";
        return 1;
    }
    std::cout << "graph_replay_tests: all checks passed.\n";
    return 0;
}
